What does this program print? (It prints no newline, so the answer is one short string.)

```cpp
#include <print>

struct Noisy {
    char c;
    ~Noisy() { std::print("{}", c); }
};

int main() {
    Noisy a{'a'};
    {
        Noisy b{'b'};
        Noisy c{'c'};
    }
    Noisy d{'d'};
    std::print("|");
}
```

